cat > /tmp/repro_fixed.py <<'EOF'
import pandas as pd
import numpy as np

def quality_counts_fixed(df: pd.DataFrame) -> dict:
    missing = int((df["reading"].isna() | df["baseline"].isna()).sum())
    undefined = int(((df["reading"] == 0) & (df["baseline"] == 0)).sum())
    return {"missing": missing, "undefined_ratio": undefined}

# Case 1: missing values
df_missing = pd.DataFrame({
    "reading": pd.Series([1.0, np.nan, 3.0], dtype="Float64"),
    "baseline": pd.Series([2.0, 4.0, np.nan], dtype="Float64")
})
print("Missing:", quality_counts_fixed(df_missing)) # Expected: {'missing': 2, 'undefined_ratio': 0}

# Case 2: 0/0
df_undefined = pd.DataFrame({
    "reading": pd.Series([0.0, 1.0], dtype="Float64"),
    "baseline": pd.Series([0.0, 2.0], dtype="Float64")
})
print("Undefined:", quality_counts_fixed(df_undefined)) # Expected: {'missing': 0, 'undefined_ratio': 1}

# Case 3: both
df_both = pd.DataFrame({
    "reading": pd.Series([0.0, np.nan, 3.0], dtype="Float64"),
    "baseline": pd.Series([0.0, 4.0, np.nan], dtype="Float64")
})
print("Both:", quality_counts_fixed(df_both)) # Expected: {'missing': 2, 'undefined_ratio': 1}
EOF
python3 /tmp/repro_fixed.py

